// Dispatch incoming partition records to thread queues based on entity key
export class OrderedEventDispatcher {
  private workerQueues: Map<string, Promise<void>> = new Map();

  dispatch(entityId: string, eventHandler: () => Promise<void>) {
    // Chain promises per entityId to guarantee sequential execution per entity
    const previousTask = this.workerQueues.get(entityId) || Promise.resolve();
    const nextTask = previousTask
      .then(eventHandler)
      .catch(err => console.error(`Error processing ${entityId}:`, err));

    this.workerQueues.set(entityId, nextTask);
  }
}
